fn makePathIfNeeded(path: []const u8) !void {
    fs.cwd().makePath(path) catch |err| switch (err) {
        error.PathAlreadyExists => {},
        else => return err,
    };
}

fn readFileAlloc(allocator: Allocator, path: []const u8, max_bytes: usize) ![]u8 {
    var file = fs.cwd().openFile(path, .{}) catch |err| switch (err) {
        error.FileNotFound => return ZKProofError.FileNotFound,
        else => return err,
    };
    defer file.close();
    return file.readToEndAlloc(allocator, max_bytes);
}

fn writeFileAll(path: []const u8, data: []const u8) !void {
    var file = try fs.cwd().createFile(path, .{ .truncate = true });
    defer file.close();
    try file.writeAll(data);
}

fn parseSnarkjsVerificationOutput(stdout: []const u8, stderr: []const u8) bool {
    const out = std.mem.trim(u8, stdout, " \t\r\n");
    const err = std.mem.trim(u8, stderr, " \t\r\n");
    if (std.mem.eql(u8, out, "OK")) return true;
    if (std.mem.eql(u8, out, "Valid")) return true;
    if (std.mem.indexOf(u8, out, "\nOK\n") != null) return true;
    if (std.mem.indexOf(u8, out, "\nValid\n") != null) return true;
    if (std.mem.indexOf(u8, err, "OK") != null and std.mem.indexOf(u8, err, "Invalid") == null) return true;
    return false;
}

fn checkTermOk(term: ChildProcess.Term) bool {
    return switch (term) {
        .Exited => |code| code == 0,
        else => false,
    };
}

fn safeRoundScaledF32(x: f32, scale: i64) !i64 {
    if (std.math.isNan(x) or std.math.isInf(x)) return ZKProofError.InvalidInput;
    const scaled: f64 = @as(f64, x) * @as(f64, @floatFromInt(scale));
    const rounded: f64 = std.math.round(scaled);
    if (rounded > @as(f64, @floatFromInt(std.math.maxInt(i64)))) return ZKProofError.InvalidInput;
    if (rounded < @as(f64, @floatFromInt(std.math.minInt(i64)))) return ZKProofError.InvalidInput;
    return @intFromFloat(rounded);
}

fn bytesToHexLower(bytes: []const u8, out: []u8) void {
    _ = std.fmt.bytesToHex(out, bytes, .lower);
}

fn randomHexSuffix() [64]u8 {
    var raw: [32]u8 = undefined;
    crypto.random.bytes(&raw);
    var hex: [64]u8 = undefined;
    bytesToHexLower(&raw, &hex);
    return hex;
}

pub const CircomProver = struct {
    allocator: Allocator,
    config: *ZKCircuitConfig,
    circuit_compiled: bool,
    keys_generated: bool,
    snarkjs_path: []const u8,
    node_path: []const u8,

    const Self = @This();

    pub fn init(allocator: Allocator, config: *ZKCircuitConfig) !*Self {
        try config.validate();

        const self = try allocator.create(Self);
        errdefer allocator.destroy(self);

        self.* = Self{
            .allocator = allocator,
            .config = config,
            .circuit_compiled = false,
            .keys_generated = false,
            .snarkjs_path = "npx",
            .node_path = "node",
        };

        try makePathIfNeeded(self.config.witness_dir);
        try makePathIfNeeded(self.config.proof_dir);
        try self.checkPrerequisites();

        return self;
    }

    pub fn deinit(self: *Self) void {
        self.allocator.destroy(self);
    }

    fn checkPrerequisites(self: *Self) !void {
        self.circuit_compiled = (fs.cwd().openFile(self.config.wasm_path, .{}) catch null) != null;
        if (self.circuit_compiled) {
            (try fs.cwd().openFile(self.config.wasm_path, .{})).close();
        }

        self.keys_generated = (fs.cwd().openFile(self.config.zkey_path, .{}) catch null) != null;
        if (self.keys_generated) {
            (try fs.cwd().openFile(self.config.zkey_path, .{})).close();
        }
    }

    fn runTool(self: *Self, argv: []const []const u8) !ChildProcess.RunResult {
        return ChildProcess.run(.{
            .allocator = self.allocator,
            .argv = argv,
            .cwd_dir = fs.cwd(),
            .max_output_bytes = self.config.max_process_output_bytes,
        }) catch |err| switch (err) {
            error.StdoutStreamTooLong => return ZKProofError.StdoutStreamTooLong,
            error.StderrStreamTooLong => return ZKProofError.StderrStreamTooLong,
            else => return err,
        };
    }

    pub fn compileCircuit(self: *Self) !void {
        const args = [_][]const u8{
            "circom",
            self.config.circuit_path,
            "--r1cs",
            "--wasm",
            "--sym",
            "-o",
            "src/zk",
        };

        var rr = try self.runTool(&args);
        defer self.allocator.free(rr.stdout);
        defer self.allocator.free(rr.stderr);

        if (!checkTermOk(rr.term)) return ZKProofError.CircomCompilationFailed;
        self.circuit_compiled = true;
    }

    pub fn setupKeys(self: *Self, ptau_path: []const u8) !void {
        const setup_args = [_][]const u8{
            self.snarkjs_path,
            "snarkjs",
            "groth16",
            "setup",
            "src/zk/inference_trace.r1cs",
            ptau_path,
            self.config.zkey_path,
        };

        var rr1 = try self.runTool(&setup_args);
        defer self.allocator.free(rr1.stdout);
        defer self.allocator.free(rr1.stderr);

        if (!checkTermOk(rr1.term)) return ZKProofError.KeysNotGenerated;

        const export_args = [_][]const u8{
            self.snarkjs_path,
            "snarkjs",
            "zkey",
            "export",
            "verificationkey",
            self.config.zkey_path,
            self.config.vkey_path,
        };

        var rr2 = try self.runTool(&export_args);
        defer self.allocator.free(rr2.stdout);
        defer self.allocator.free(rr2.stderr);

        if (!checkTermOk(rr2.term)) return ZKProofError.KeysNotGenerated;

        self.keys_generated = true;
    }

    pub fn generateWitness(self: *Self, input_json_path: []const u8, witness_path: []const u8) !void {
        if (!self.circuit_compiled) return ZKProofError.CircuitNotCompiled;

        const witness_gen_path = "src/zk/inference_trace_js/generate_witness.js";

        const args = [_][]const u8{
            self.node_path,
            witness_gen_path,
            self.config.wasm_path,
            input_json_path,
            witness_path,
        };

        var rr = try self.runTool(&args);
        defer self.allocator.free(rr.stdout);
        defer self.allocator.free(rr.stderr);

        if (!checkTermOk(rr.term)) return ZKProofError.WitnessGenerationFailed;
    }

    pub fn generateProof(self: *Self, witness_path: []const u8, proof_path: []const u8, public_path: []const u8) !void {
        if (!self.keys_generated) return ZKProofError.KeysNotGenerated;

        const args = [_][]const u8{
            self.snarkjs_path,
            "snarkjs",
            "groth16",
            "prove",
            self.config.zkey_path,
            witness_path,
            proof_path,
            public_path,
        };

        var rr = try self.runTool(&args);
        defer self.allocator.free(rr.stdout);
        defer self.allocator.free(rr.stderr);

        if (!checkTermOk(rr.term)) return ZKProofError.ProofGenerationFailed;
    }

    pub fn verifyProof(self: *Self, proof_path: []const u8, public_path: []const u8) !bool {
        const args = [_][]const u8{
            self.snarkjs_path,
            "snarkjs",
            "groth16",
            "verify",
            self.config.vkey_path,
            public_path,
            proof_path,
        };

        var rr = try self.runTool(&args);
        defer self.allocator.free(rr.stdout);
        defer self.allocator.free(rr.stderr);

        if (!checkTermOk(rr.term)) return false;
        return parseSnarkjsVerificationOutput(rr.stdout, rr.stderr);
    }
};

pub const InferenceWitness = struct {
    allocator: Allocator,
    tokens: []i64,
    expected_output: []i64,
    layer_weights_s: [][]i64,
    layer_weights_t: [][]i64,
    input_commitment: [32]u8,
    output_commitment: [32]u8,
    layer_commitments: [][32]u8,
    max_error_squared: i64,
    num_layers: usize,
    dim: usize,

    const Self = @This();

    pub fn init(allocator: Allocator, num_layers: usize, dim: usize) !*Self {
        if (num_layers == 0 or dim == 0) return ZKProofError.InvalidConfig;

        const self = try allocator.create(Self);
        errdefer allocator.destroy(self);

        const tokens = try allocator.alloc(i64, dim);
        errdefer allocator.free(tokens);
        @memset(tokens, 0);

        const expected_output = try allocator.alloc(i64, dim);
        errdefer allocator.free(expected_output);
        @memset(expected_output, 0);

        const layer_commitments = try allocator.alloc([32]u8, num_layers);
        errdefer allocator.free(layer_commitments);
        @memset(layer_commitments, std.mem.zeroes([32]u8));

        const layer_weights_s = try allocator.alloc([]i64, num_layers);
        errdefer allocator.free(layer_weights_s);

        const layer_weights_t = try allocator.alloc([]i64, num_layers);
        errdefer allocator.free(layer_weights_t);

        const layer_len = dim * dim;

        var layer_idx: usize = 0;
        while (layer_idx < num_layers) : (layer_idx += 1) {
            layer_weights_s[layer_idx] = try allocator.alloc(i64, layer_len);
            errdefer allocator.free(layer_weights_s[layer_idx]);
            @memset(layer_weights_s[layer_idx], 0);

            layer_weights_t[layer_idx] = try allocator.alloc(i64, layer_len);
            errdefer allocator.free(layer_weights_t[layer_idx]);
            @memset(layer_weights_t[layer_idx], 0);
        }

        self.* = Self{
            .allocator = allocator,
            .tokens = tokens,
            .expected_output = expected_output,
            .layer_weights_s = layer_weights_s,
            .layer_weights_t = layer_weights_t,
            .input_commitment = std.mem.zeroes([32]u8),
            .output_commitment = std.mem.zeroes([32]u8),
            .layer_commitments = layer_commitments,
            .max_error_squared = 1_000_000,
            .num_layers = num_layers,
            .dim = dim,
        };

        return self;
    }

    pub fn deinit(self: *Self) void {
        self.allocator.free(self.tokens);
        self.allocator.free(self.expected_output);
        self.allocator.free(self.layer_commitments);

        var layer_idx: usize = 0;
        while (layer_idx < self.num_layers) : (layer_idx += 1) {
            self.allocator.free(self.layer_weights_s[layer_idx]);
            self.allocator.free(self.layer_weights_t[layer_idx]);
        }
        self.allocator.free(self.layer_weights_s);
        self.allocator.free(self.layer_weights_t);
        self.allocator.destroy(self);
    }

    fn idx(self: *const Self, i: usize, j: usize) usize {
        return i * self.dim + j;
    }

    pub fn setTokens(self: *Self, input_tokens: []const f32, scale: i64) !void {
        if (input_tokens.len == 0) return ZKProofError.InvalidInput;
        if (input_tokens.len != self.dim) return ZKProofError.InvalidInput;

        var i: usize = 0;
        while (i < self.dim) : (i += 1) {
            self.tokens[i] = try safeRoundScaledF32(input_tokens[i], scale);
        }
    }

    pub fn setExpectedOutput(self: *Self, output: []const f32, scale: i64) !void {
        if (output.len == 0) return ZKProofError.InvalidOutput;
        if (output.len != self.dim) return ZKProofError.InvalidOutput;

        var i: usize = 0;
        while (i < self.dim) : (i += 1) {
            self.expected_output[i] = try safeRoundScaledF32(output[i], scale);
        }
    }

    pub fn setLayerWeights(self: *Self, layer: usize, weights_s: []const []const f32, weights_t: []const []const f32, scale: i64) !void {
        if (layer >= self.num_layers) return ZKProofError.InvalidInput;
        if (weights_s.len != self.dim or weights_t.len != self.dim) return ZKProofError.InvalidInput;

        var i: usize = 0;
        while (i < self.dim) : (i += 1) {
            if (weights_s[i].len != self.dim or weights_t[i].len != self.dim) return ZKProofError.InvalidInput;

            var j: usize = 0;
            while (j < self.dim) : (j += 1) {
                self.layer_weights_s[layer][self.idx(i, j)] = try safeRoundScaledF32(weights_s[i][j], scale);
                self.layer_weights_t[layer][self.idx(i, j)] = try safeRoundScaledF32(weights_t[i][j], scale);
            }
        }
    }

    pub fn computeCommitments(self: *Self) void {
        var input_hasher = Blake3.init(.{});
        input_hasher.update("INFER_INPUT_V1");
        for (self.tokens) |token| {
            input_hasher.update(std.mem.asBytes(&token));
        }
        input_hasher.final(&self.input_commitment);

        var output_hasher = Blake3.init(.{});
        output_hasher.update("INFER_OUTPUT_V1");
        for (self.expected_output) |out| {
            output_hasher.update(std.mem.asBytes(&out));
        }
        output_hasher.final(&self.output_commitment);

        var layer_idx: usize = 0;
        while (layer_idx < self.num_layers) : (layer_idx += 1) {
            var h = Blake3.init(.{});
            h.update("INFER_LAYER_V1");
            h.update(std.mem.asBytes(&layer_idx));
            var k: usize = 0;
            while (k < self.layer_weights_s[layer_idx].len) : (k += 1) {
                h.update(std.mem.asBytes(&self.layer_weights_s[layer_idx][k]));
            }
            k = 0;
            while (k < self.layer_weights_t[layer_idx].len) : (k += 1) {
                h.update(std.mem.asBytes(&self.layer_weights_t[layer_idx][k]));
            }
            h.final(&self.layer_commitments[layer_idx]);
        }
    }

    fn writeHexString(writer: anytype, bytes: []const u8) !void {
        var buf: [64]u8 = undefined;
        _ = std.fmt.bytesToHex(&buf, bytes, .lower);
        try writer.print("\"{s}\"", .{buf});
    }

    pub fn toJson(self: *Self, path: []const u8) !void {
        var file = try fs.cwd().createFile(path, .{ .truncate = true });
        defer file.close();

        var bw = std.io.bufferedWriter(file.writer());
        const writer = bw.writer();

        try writer.writeAll("{\n");

        try writer.writeAll("  \"tokens\": [");
        var i: usize = 0;
        while (i < self.dim) : (i += 1) {
            if (i > 0) try writer.writeAll(", ");
            try writer.print("{}", .{self.tokens[i]});
        }
        try writer.writeAll("],\n");

        try writer.writeAll("  \"layer_weights_s\": [\n");
        var layer: usize = 0;
        while (layer < self.num_layers) : (layer += 1) {
            try writer.writeAll("    [\n");
            i = 0;
            while (i < self.dim) : (i += 1) {
                try writer.writeAll("      [");
                var j: usize = 0;
                while (j < self.dim) : (j += 1) {
                    if (j > 0) try writer.writeAll(", ");
                    try writer.print("{}", .{self.layer_weights_s[layer][self.idx(i, j)]});
                }
                try writer.writeAll("]");
                if (i + 1 < self.dim) try writer.writeAll(",");
                try writer.writeAll("\n");
            }
            try writer.writeAll("    ]");
            if (layer + 1 < self.num_layers) try writer.writeAll(",");
            try writer.writeAll("\n");
        }
        try writer.writeAll("  ],\n");

        try writer.writeAll("  \"layer_weights_t\": [\n");
        layer = 0;
        while (layer < self.num_layers) : (layer += 1) {
            try writer.writeAll("    [\n");
            i = 0;
            while (i < self.dim) : (i += 1) {
                try writer.writeAll("      [");
                var j: usize = 0;
                while (j < self.dim) : (j += 1) {
                    if (j > 0) try writer.writeAll(", ");
                    try writer.print("{}", .{self.layer_weights_t[layer][self.idx(i, j)]});
                }
                try writer.writeAll("]");
                if (i + 1 < self.dim) try writer.writeAll(",");
                try writer.writeAll("\n");
            }
            try writer.writeAll("    ]");
            if (layer + 1 < self.num_layers) try writer.writeAll(",");
            try writer.writeAll("\n");
        }
        try writer.writeAll("  ],\n");

        try writer.writeAll("  \"expected_output\": [");
        i = 0;
        while (i < self.dim) : (i += 1) {
            if (i > 0) try writer.writeAll(", ");
            try writer.print("{}", .{self.expected_output[i]});
        }
        try writer.writeAll("],\n");

        try writer.writeAll("  \"input_commitment\": ");
        try writeHexString(writer, &self.input_commitment);
        try writer.writeAll(",\n");

        try writer.writeAll("  \"output_commitment\": ");
        try writeHexString(writer, &self.output_commitment);
        try writer.writeAll(",\n");

        try writer.writeAll("  \"layer_commitments\": [");
        layer = 0;
        while (layer < self.num_layers) : (layer += 1) {
            if (layer > 0) try writer.writeAll(", ");
            try writeHexString(writer, &self.layer_commitments[layer]);
        }
        try writer.writeAll("],\n");

        try writer.print("  \"max_error_squared\": {}\n", .{self.max_error_squared});
        try writer.writeAll("}\n");

        try bw.flush();
    }
};

pub const ZKInferenceProver = struct {
    allocator: Allocator,
    config: *ZKCircuitConfig,
    prover: *CircomProver,
    proof_counter: u64,

    const Self = @This();

    pub fn init(allocator: Allocator) !*Self {
        const config = try ZKCircuitConfig.defaultConfig(allocator);
        errdefer allocator.destroy(config);

        try config.validate();

        const prover = CircomProver.init(allocator, config) catch |err| {
            allocator.destroy(config);
            return err;
        };
        errdefer prover.deinit();

        const self = try allocator.create(Self);
        errdefer allocator.destroy(self);

        self.* = Self{
            .allocator = allocator,
            .config = config,
            .prover = prover,
            .proof_counter = 0,
        };

        return self;
    }

    pub fn deinit(self: *Self) void {
        self.prover.deinit();
        self.allocator.destroy(self.config);
        self.allocator.destroy(self);
    }

    pub fn proveInference(
        self: *Self,
        input: []const f32,
        output: []const f32,
        layer_weights_s: []const []const []const f32,
        layer_weights_t: []const []const []const f32,
    ) !*ZKProofBundle {
        if (layer_weights_s.len != self.config.num_layers or layer_weights_t.len != self.config.num_layers) {
            return ZKProofError.InvalidInput;
        }

        const witness = try InferenceWitness.init(
            self.allocator,
            self.config.num_layers,
            self.config.embedding_dim,
        );
        defer witness.deinit();

        const scale: i64 = 1_000_000;
        try witness.setTokens(input, scale);
        try witness.setExpectedOutput(output, scale);

        var layer: usize = 0;
        while (layer < self.config.num_layers) : (layer += 1) {
            try witness.setLayerWeights(layer, layer_weights_s[layer], layer_weights_t[layer], scale);
        }

        witness.computeCommitments();

        const input_path = try std.fmt.allocPrint(
            self.allocator,
            "{s}/input_{d}.json",
            .{ self.config.witness_dir, self.proof_counter },
        );
        defer self.allocator.free(input_path);

        try witness.toJson(input_path);

        const witness_path = try std.fmt.allocPrint(
            self.allocator,
            "{s}/witness_{d}.wtns",
            .{ self.config.witness_dir, self.proof_counter },
        );
        defer self.allocator.free(witness_path);

        try self.prover.generateWitness(input_path, witness_path);

        const proof_path = try std.fmt.allocPrint(
            self.allocator,
            "{s}/proof_{d}.json",
            .{ self.config.proof_dir, self.proof_counter },
        );
        defer self.allocator.free(proof_path);

        const public_path = try std.fmt.allocPrint(
            self.allocator,
            "{s}/public_{d}.json",
            .{ self.config.proof_dir, self.proof_counter },
        );
        defer self.allocator.free(public_path);

        try self.prover.generateProof(witness_path, proof_path, public_path);

        const bundle = try ZKProofBundle.init(self.allocator);
        errdefer bundle.deinit();

        self.allocator.free(bundle.proof_json);
        bundle.proof_json = try readFileAlloc(self.allocator, proof_path, self.config.max_file_bytes);

        self.allocator.free(bundle.public_json);
        bundle.public_json = try readFileAlloc(self.allocator, public_path, self.config.max_file_bytes);

        bundle.verification_status = try self.prover.verifyProof(proof_path, public_path);

        if (self.proof_counter == std.math.maxInt(u64)) return ZKProofError.InvalidOutput;
        self.proof_counter += 1;

        return bundle;
    }

    pub fn verifyProofBundle(self: *Self, bundle: *ZKProofBundle) !bool {
        const suffix = randomHexSuffix();

        const proof_path = try std.fmt.allocPrint(
            self.allocator,
            "{s}/verify_{s}_proof.json",
            .{ self.config.proof_dir, suffix[0..16] },
        );
        defer self.allocator.free(proof_path);

        const public_path = try std.fmt.allocPrint(
            self.allocator,
            "{s}/verify_{s}_public.json",
            .{ self.config.proof_dir, suffix[16..32] },
        );
        defer self.allocator.free(public_path);

        try writeFileAll(proof_path, bundle.proof_json);
        errdefer fs.cwd().deleteFile(proof_path) catch {};

        try writeFileAll(public_path, bundle.public_json);
        errdefer fs.cwd().deleteFile(public_path) catch {};

        const result = try self.prover.verifyProof(proof_path, public_path);

        fs.cwd().deleteFile(proof_path) catch {};
        fs.cwd().deleteFile(public_path) catch {};

        return result;
    }
};

pub const CommitmentScheme = struct {
    allocator: Allocator,
    commitments: AutoHashMap([32]u8, Commitment),

    const Self = @This();

    pub const Commitment = struct {
        value_hash: [32]u8,
        nonce: [32]u8,
        timestamp_ns: i128,
        blinding_factor: [32]u8,
    };

    pub fn init(allocator: Allocator) !*Self {
        const self = try allocator.create(Self);
        errdefer allocator.destroy(self);

        self.* = Self{
            .allocator = allocator,
            .commitments = AutoHashMap([32]u8, Commitment).init(allocator),
        };
        return self;
    }

    pub fn deinit(self: *Self) void {
        self.commitments.deinit();
        self.allocator.destroy(self);
    }

    pub fn commit(self: *Self, value: []const u8) ![32]u8 {
        var nonce: [32]u8 = undefined;
        crypto.random.bytes(&nonce);

        var blinding: [32]u8 = undefined;
        crypto.random.bytes(&blinding);

        var hasher = Blake3.init(.{});
        hasher.update("COMMIT_V1");
        hasher.update(value);
        hasher.update(&nonce);
        hasher.update(&blinding);

        var commitment_hash: [32]u8 = undefined;
        hasher.final(&commitment_hash);

        if (self.commitments.contains(commitment_hash)) return ZKProofError.CommitmentCollision;

        var value_hasher = Sha256.init(.{});
        value_hasher.update("COMMIT_VALUE_V1");
        value_hasher.update(value);

        var value_hash: [32]u8 = undefined;
        value_hasher.final(&value_hash);

        const commitment = Commitment{
            .value_hash = value_hash,
            .nonce = nonce,
            .timestamp_ns = std.time.nanoTimestamp(),
            .blinding_factor = blinding,
        };

        try self.commitments.put(commitment_hash, commitment);
        return commitment_hash;
    }

    pub fn verify(
        self: *Self,
        commitment_hash: [32]u8,
        revealed_value: []const u8,
        revealed_nonce: [32]u8,
        revealed_blinding: [32]u8,
    ) !bool {
        const commitment = self.commitments.get(commitment_hash) orelse return false;

        if (!crypto.utils.timingSafeEql([32]u8, commitment.nonce, revealed_nonce)) return false;
        if (!crypto.utils.timingSafeEql([32]u8, commitment.blinding_factor, revealed_blinding)) return false;

        var hasher = Blake3.init(.{});
        hasher.update("COMMIT_V1");
        hasher.update(revealed_value);
        hasher.update(&revealed_nonce);
        hasher.update(&revealed_blinding);

        var computed_commitment: [32]u8 = undefined;
        hasher.final(&computed_commitment);

        if (!crypto.utils.timingSafeEql([32]u8, commitment_hash, computed_commitment)) return false;

        var value_hasher = Sha256.init(.{});
        value_hasher.update("COMMIT_VALUE_V1");
        value_hasher.update(revealed_value);

        var computed_value_hash: [32]u8 = undefined;
        value_hasher.final(&computed_value_hash);

        return crypto.utils.timingSafeEql([32]u8, commitment.value_hash, computed_value_hash);
    }
};

pub const RangeProof = struct {
    allocator: Allocator,
    min_value: i64,
    max_value: i64,
    proof_bits: ArrayList(ProofBit),

    const ProofBit = struct {
        commitment: [32]u8,
        opening: [32]u8,
        bit_value: u1,
    };

    const Self = @This();

    pub fn init(allocator: Allocator, min: i64, max: i64) !*Self {
        if (max < min) return ZKProofError.InvalidRange;

        const self = try allocator.create(Self);
        errdefer allocator.destroy(self);

        self.* = Self{
            .allocator = allocator,
            .min_value = min,
            .max_value = max,
            .proof_bits = ArrayList(ProofBit).init(allocator),
        };
        return self;
    }

    pub fn deinit(self: *Self) void {
        self.proof_bits.deinit();
        self.allocator.destroy(self);
