        if (span == 0) return ZKProofError.InvalidRange;
        return std.math.log2_int_ceil(u64, span);
    }

    pub fn prove(self: *Self, value: i64) !void {
        if (value < self.min_value or value > self.max_value) return ZKProofError.ValueOutOfRange;

        self.proof_bits.clearRetainingCapacity();

        const bits_needed = try self.bitsNeeded();
        if (bits_needed > @bitSizeOf(i64)) return ZKProofError.InvalidRange;

        const normalized: u64 = @intCast(@as(i128, value) - @as(i128, self.min_value));

        var i: usize = 0;
        while (i < bits_needed) : (i += 1) {
            const bit: u1 = @intCast((normalized >> @intCast(i)) & 1);

            var nonce: [32]u8 = undefined;
            crypto.random.bytes(&nonce);

            var hasher = Blake3.init(.{});
            hasher.update("RANGEBIT_V1");
            hasher.update(std.mem.asBytes(&i));
            hasher.update(&[_]u8{bit});
            hasher.update(&nonce);

            var commitment: [32]u8 = undefined;
            hasher.final(&commitment);

            try self.proof_bits.append(ProofBit{
                .commitment = commitment,
                .opening = nonce,
                .bit_value = bit,
            });
        }
    }

    pub fn verify(self: *Self) !bool {
        const bits_needed = try self.bitsNeeded();
        if (self.proof_bits.items.len != bits_needed) return false;
        if (bits_needed > @bitSizeOf(i64)) return false;

        var reconstructed: u64 = 0;

        var i: usize = 0;
        while (i < self.proof_bits.items.len) : (i += 1) {
            const bit_proof = self.proof_bits.items[i];

            var hasher = Blake3.init(.{});
            hasher.update("RANGEBIT_V1");
            hasher.update(std.mem.asBytes(&i));
            hasher.update(&[_]u8{bit_proof.bit_value});
            hasher.update(&bit_proof.opening);

