    merkle_root: [32]u8,
    path: ArrayList([32]u8),
    directions: ArrayList(bool),

    const Self = @This();

    pub fn init(allocator: Allocator) !*Self {
        const self = try allocator.create(Self);
        errdefer allocator.destroy(self);

        self.* = Self{
            .allocator = allocator,
            .merkle_root = std.mem.zeroes([32]u8),
            .path = ArrayList([32]u8).init(allocator),
            .directions = ArrayList(bool).init(allocator),
        };
        return self;
    }

    pub fn deinit(self: *Self) void {
        self.path.deinit();
        self.directions.deinit();
        self.allocator.destroy(self);
    }

    fn hashLeaf(elem: []const u8) [32]u8 {
        var hasher = Sha256.init(.{});
        hasher.update("MERKLE_LEAF_V1");
        hasher.update(elem);
        var h: [32]u8 = undefined;
        hasher.final(&h);
        return h;
    }

    fn hashNode(left: *const [32]u8, right: *const [32]u8) [32]u8 {
        var hasher = Sha256.init(.{});
        hasher.update("MERKLE_NODE_V1");
        hasher.update(left);
        hasher.update(right);
        var h: [32]u8 = undefined;
        hasher.final(&h);
        return h;
    }

    pub fn buildMerkleTree(self: *Self, elements: []const []const u8) ![32]u8 {
        if (elements.len == 0) return ZKProofError.EmptySet;

        var current = ArrayList([32]u8).init(self.allocator);
        defer current.deinit();

        for (elements) |e| {
            if (e.len == 0) return ZKProofError.InvalidInput;
            try current.append(hashLeaf(e));
        }

        while (current.items.len > 1) {
            var next = ArrayList([32]u8).init(self.allocator);
            defer next.deinit();

            var i: usize = 0;
            while (i < current.items.len) : (i += 2) {
                const left = &current.items[i];
                const right = if (i + 1 < current.items.len) &current.items[i + 1] else &current.items[i];
                try next.append(hashNode(left, right));
            }

            current.clearRetainingCapacity();
            try current.appendSlice(next.items);
        }

        self.merkle_root = current.items[0];
        return self.merkle_root;
    }

    pub fn generateProof(self: *Self, elements: []const []const u8, index: usize) !void {
        if (elements.len == 0) return ZKProofError.EmptySet;
        if (index >= elements.len) return ZKProofError.InvalidIndex;

        self.path.clearRetainingCapacity();
        self.directions.clearRetainingCapacity();

        var current = ArrayList([32]u8).init(self.allocator);
        defer current.deinit();

        for (elements) |e| {
            if (e.len == 0) return ZKProofError.InvalidInput;
            try current.append(hashLeaf(e));
        }

        var current_index = index;

        while (current.items.len > 1) {
            const is_right = (current_index % 2) == 1;
            const sibling_index: usize = if (is_right) current_index - 1 else current_index + 1;

            const sibling = if (sibling_index < current.items.len) current.items[sibling_index] else current.items[current_index];
            try self.path.append(sibling);
            try self.directions.append(is_right);

