                h2.inputs[0] <== h.out;
                h2.inputs[1] <== intermediate[chunk - 1];
                intermediate[chunk] <== h2.out;
            } else {
                intermediate[chunk] <== h.out;
            }
        }
    }

    out <== intermediate[num_chunks - 1];
}

template SafeIsZero() {
    signal input in;
    signal output out;

    signal inv;
    inv <-- in != 0 ? 1 / in : 0;

    signal prod;
    prod <== in * inv;

    out <== 1 - prod;

