        eq_checks[i].a <== pedersen_commits[i].commitment;
        eq_checks[i].b <== commitments[i];

        bit_valid[i] <== eq_checks[i].out;
    }

    signal all_valid[bits + 1];
    all_valid[0] <== 1;
    for (var i = 0; i < bits; i++) {
